from time import time


class Stopwatch:
    """ Basic tool for measuring elapsed time. """

    def __init__(self):
        self._start_time = 0.0
        self._stop_time = 0.0

    def start(self):
        """
        Starts time measurement.
        If measurement was already started or stopped then restarts it.
        """
        self._start_time = time()
        self._stop_time = 0.0

    def stop(self):
        """
        Stops time measurement.
        Does nothing if measurement was not started or already stopped.
        """
        if self._start_time and not self._stop_time:
            self._stop_time = time()

    def get_elapsed_seconds(self) -> int:
        """
        Reads current time measurement in seconds.
        If measurement was not started returns zero.
        If measurement was not stopped returns time elapsed up to this point and does not stop measurement.
        :return: elapsed time rounded down to fully elapsed seconds;
                 i.e. if 1.9 seconds elapsed then 1 is returned.
        """
        if not self._start_time:
            return 0

        stop_time = self._stop_time if self._stop_time else time()
        return int(stop_time - self._start_time)

    def reset(self):
        """
        Resets current time measurement.
        """
        self._start_time = 0.0
        self._stop_time = 0.0
